// [S4] Three-portal family features — GET /dashboard/family.
import 'package:family_veda/models/appointment.dart';
import 'package:family_veda/models/doctor_summary.dart';

class FamilyDashboard {
  const FamilyDashboard({
    required this.role,
    required this.memberCount,
    required this.minorCount,
    required this.openCases,
    required this.approvedGuidanceCount,
    required this.unreadNotifications,
    this.familyId,
    this.familyName,
    this.familyCode,
    this.pendingJoinRequests = 0,
    this.nextAppointment,
    this.familyDoctor,
    this.recentActivity = const [],
  });

  factory FamilyDashboard.fromJson(Map<String, dynamic> json) => FamilyDashboard(
    role: (json['role'] as String?) ?? 'AdultMember',
    familyId: json['familyId'] as String?,
    familyName: json['familyName'] as String?,
    familyCode: json['familyCode'] as String?,
    memberCount: (json['memberCount'] as num?)?.toInt() ?? 0,
    minorCount: (json['minorCount'] as num?)?.toInt() ?? 0,
    pendingJoinRequests: (json['pendingJoinRequests'] as num?)?.toInt() ?? 0,
    nextAppointment: json['nextAppointment'] == null
        ? null
        : Appointment.fromJson(json['nextAppointment'] as Map<String, dynamic>),
    openCases: (json['openCases'] as num?)?.toInt() ?? 0,
    approvedGuidanceCount: (json['approvedGuidanceCount'] as num?)?.toInt() ?? 0,
    familyDoctor: json['familyDoctor'] == null
        ? null
        : DoctorSummary.fromJson(json['familyDoctor'] as Map<String, dynamic>),
    unreadNotifications: (json['unreadNotifications'] as num?)?.toInt() ?? 0,
    recentActivity: ((json['recentActivity'] as List?) ?? const [])
        .map((entry) => entry.toString())
        .toList(growable: false),
  );

  final String role;
  final String? familyId;
  final String? familyName;
  final String? familyCode;
  final int memberCount;
  final int minorCount;
  final int pendingJoinRequests;
  final Appointment? nextAppointment;
  final int openCases;
  final int approvedGuidanceCount;
  final DoctorSummary? familyDoctor;
  final int unreadNotifications;
  final List<String> recentActivity;

  bool get isHead => role == 'Head' || role == 'FamilyHead';
}
